import itertools

def solve_small(n_guests, max_rounds):
    count_at_least_one_remains = 0
    total_permutations = 0

    for p in itertools.permutations(range(n_guests)):
        total_permutations += 1
        # current_guests is a list of (guest_id, tag_id)
        # guest_id is the original index 0..n_guests-1
        current_guests = []
        for i in range(n_guests):
            current_guests.append({'id': i, 'tag': p[i]})

        for round_num in range(1, max_rounds + 1):
            # i) Guests with their own name tag exit
            next_guests = []
            for g in current_guests:
                if g['tag'] != g['id']:
                    next_guests.append(g)

            current_guests = next_guests
            if not current_guests:
                break

            # ii) Remaining guests pass tags to the right
            # The guest to the right of current_guests[j] is current_guests[(j+1)%len(current_guests)]
            new_tags = [None] * len(current_guests)
            for j in range(len(current_guests)):
                # guest j passes their tag to guest j+1
                pass_to_idx = (j + 1) % len(current_guests)
                new_tags[pass_to_idx] = current_guests[j]['tag']

            for j in range(len(current_guests)):
                current_guests[j]['tag'] = new_tags[j]

        if current_guests:
            count_at_least_one_remains += 1

    return count_at_least_one_remains, total_permutations

