# Use a simple recursive permanent
def perm_recursive(matrix):
    n = len(matrix)
    if n == 0:
        return 1
    res = 0
    for j in range(n):
        sub_matrix = [row[:j] + row[j+1:] for row in matrix[1:]]
        res += matrix[0][j] * perm_recursive(sub_matrix)
    return res

def get_f(n, k):
    # First row has 1s at 0, n-1, n-2, ..., n-k
    first_row = [0] * n
    first_row[0] = 1
    for i in range(1, k + 1):
        first_row[n - i] = 1

    matrix = []
    for i in range(n):
        row = [0] * n
        for j in range(n):
            if first_row[(j - i) % n] == 1:
                row[j] = 1
        matrix.append(row)

    return perm_recursive(matrix)

