import itertools

def simulate_rule_b(N, sigma, rounds):
    # seats[i] = guest_id if seat i is occupied, else None
    # tags[i] = tag_id if seat i has a tag, else None
    seats = list(range(N))
    tags = list(sigma)

    for r in range(rounds):
        to_remove = []
        for i in range(N):
            if seats[i] is not None and tags[i] == seats[i]:
                to_remove.append(i)

        # Guests leave
        for i in to_remove:
            seats[i] = None
            tags[i] = None

        # Remaining guests pass their tags
        remaining_seats = [i for i in range(N) if seats[i] is not None]
        if not remaining_seats:
            return False

        new_tags = [None] * N
        for i in remaining_seats:
            # Guest at seat i passes tag tags[i] to the guest at the next occupied seat
            current_pos = remaining_seats.index(i)
            next_pos = (current_pos + 1) % len(remaining_seats)
            next_seat = remaining_seats[next_pos]
            new_tags[next_seat] = tags[i]

        tags = new_tags

    return any(seats[i] is not None for i in range(N))

def count_survivors(N, rounds):
    count = 0
    for sigma in itertools.permutations(range(N)):
        if simulate_rule_b(N, sigma, rounds):
            count += 1
    return count

