def simulate_fixed(N, rounds, p):
    # p[i] is the tag held by guest i
    tag_pos = [0] * N
    for i in range(N):
        tag_pos[p[i]] = i

    S = set(range(N))
    removed_tags = [False] * N

    for r in range(rounds):
        # 1. Guests who have their own tag leave
        G_leave = []
        for x in range(N):
            if not removed_tags[x] and tag_pos[x] in S and tag_pos[x] == x:
                G_leave.append(x)

        # These tags and guests are gone
        for x in G_leave:
            removed_tags[x] = True
            if x in S:
                S.remove(x)

        # 2. Remaining guests pass their name tags
        # Guests in S currently have some tags.
        # Let's find them.
        guest_has_tag = [None] * N
        for x in range(N):
            if not removed_tags[x] and tag_pos[x] in S:
                guest_has_tag[tag_pos[x]] = x

        sorted_S = sorted(list(S))
        if not sorted_S:
            break

        current_tags = [guest_has_tag[g] for g in sorted_S]

        # The tag at g_i moves to g_{i+1}.
        # So the new tag at g_{i+1} is the tag that was at g_i.
        # This means the tags are shifted one position to the right.
        # The tag at g_m moves to g_1.

        # New tags at sorted_S:
        # g_1 gets tag from g_m
        # g_2 gets tag from g_1
        # ...
        # g_m gets tag from g_{m-1}

        # current_tags is [T_{g_1}, T_{g_2}, ..., T_{g_m}]
        # We want new_tags to be [T_{g_m}, T_{g_1}, ..., T_{g_{m-1}}]

        new_tags = [None] * len(sorted_S)
        for i in range(len(sorted_S)):
            new_tags[i] = current_tags[(i - 1) % len(sorted_S)]

        for i, g in enumerate(sorted_S):
            if new_tags[i] is not None:
                tag_pos[new_tags[i]] = g
                guest_has_tag[g] = new_tags[i]

    return len(S) > 0

